fn status_error(c: &mut Ctx) -> ApiResult {
    Flow::ret(u64::from(super::super::nt::status_to_error(c.u32(0)?)))
}
fn self_process(c: &Ctx, handle: u64) -> bool {
    handle == c.arch().ptr(u64::MAX)
}
fn terminate_process(c: &mut Ctx) -> ApiResult {
    let (handle, status) = (c.ptr(0)?, c.u32(1)?);
    if !self_process(c, handle) && handle != 0 {
        return Flow::ret(STATUS_INVALID_HANDLE.into());
    }
    Ok(Flow::TerminateProcess(status))
}
fn terminate_thread(c: &mut Ctx) -> ApiResult {
    let (handle, status) = (c.ptr(0)?, c.u32(1)?);
    if handle != c.arch().ptr(u64::MAX - 1) && handle != 0 {
        return Flow::ret(STATUS_INVALID_HANDLE.into());
    }
    Ok(Flow::TerminateThread(status))
}
fn close(c: &mut Ctx) -> ApiResult {
    let handle = c.ptr(0)?;
    Flow::ret(
        if c.p.objects.close(handle).is_ok() {
            STATUS_SUCCESS
        } else {
            STATUS_INVALID_HANDLE
        }
        .into(),
    )
}
fn alloc(c: &mut Ctx) -> ApiResult {
    let (handle, base_ptr, zero, size_ptr, flags, protection) = (
        c.ptr(0)?,
        c.ptr(1)?,
        c.ptr(2)?,
        c.ptr(3)?,
        c.u32(4)?,
        c.u32(5)?,
    );
    if !self_process(c, handle) {
        return Flow::ret(STATUS_INVALID_HANDLE.into());
    }
    if zero != 0 {
        return Err(c.unsupported("NtAllocateVirtualMemory ZeroBits"));
    }
    let (base, size) = (c.read_ptr(base_ptr)?, c.read_ptr(size_ptr)?);
    c.write_ptr(base_ptr, base)?;
    c.write_ptr(size_ptr, size)?;
    match c
        .p
        .vm
        .allocate((base != 0).then_some(base), size, flags, protection)
    {
        Ok((base, size)) => {
            c.write_ptr(base_ptr, base)?;
            c.write_ptr(size_ptr, size)?;
            Flow::ret(0)
        }
        Err(e) => Flow::ret(e.status().into()),
    }
}
fn free(c: &mut Ctx) -> ApiResult {
    let (handle, base_ptr, size_ptr, flags) = (c.ptr(0)?, c.ptr(1)?, c.ptr(2)?, c.u32(3)?);
    if !self_process(c, handle) {
        return Flow::ret(STATUS_INVALID_HANDLE.into());
    }
    let (base, size) = (c.read_ptr(base_ptr)?, c.read_ptr(size_ptr)?);
    c.write_ptr(base_ptr, base)?;
    c.write_ptr(size_ptr, size)?;
    match c.p.vm.free(base, size, flags) {
        Ok((base, size)) => {
            c.write_ptr(base_ptr, base)?;
            c.write_ptr(size_ptr, size)?;
            Flow::ret(0)
        }
        Err(e) => Flow::ret(e.status().into()),
    }
}
fn protect(c: &mut Ctx) -> ApiResult {
    let (handle, base_ptr, size_ptr, protection, old_ptr) =
        (c.ptr(0)?, c.ptr(1)?, c.ptr(2)?, c.u32(3)?, c.ptr(4)?);
    if !self_process(c, handle) {
        return Flow::ret(STATUS_INVALID_HANDLE.into());
    }
    let (base, size) = (c.read_ptr(base_ptr)?, c.read_ptr(size_ptr)?);
    c.write_ptr(base_ptr, base)?;
    c.write_ptr(size_ptr, size)?;
    c.mem().w32(old_ptr, c.mem().u32(old_ptr)?)?;
    match c.p.vm.protect(base, size, protection) {
        Ok(old) => {
            let start = base & !0xFFF;
            let end = base
                .checked_add(size)
                .and_then(|v| v.checked_add(0xFFF))
                .ok_or(super::super::memory::MemFault {
                    addr: u64::MAX,
                    write: false,
                })?
                & !0xFFF;
            c.write_ptr(base_ptr, start)?;
            c.write_ptr(size_ptr, end - start)?;
            c.mem().w32(old_ptr, old)?;
            Flow::ret(0)
        }
        Err(e) => {
            if c.p.vm.is_nls_view(base) && e == super::super::memory::VmError::InvalidProtection
                || c.p.vm.is_data_view(base)
                    && matches!(
                        e,
                        super::super::memory::VmError::SectionProtection
                            | super::super::memory::VmError::InvalidParameter4
                    )
            {
                c.mem().w32(old_ptr, super::super::memory::prot::NOACCESS)?;
            }
            Flow::ret(e.status().into())
        }
    }
}
fn continue_context(c: &mut Ctx) -> ApiResult {
    if c.u32(1)? != 0 {
        return Err(c.unsupported("NtContinue alertable APC delivery"));
    }
    let address = c.ptr(0)?;
    if address % super::super::context::RegContext::align(c.arch()) != 0 {
        return Flow::ret(STATUS_INVALID_PARAMETER.into());
    }
    let context = super::super::context::RegContext::read(c.mem(), c.arch(), address)?;
    if let Err(status) = context.validate(&c.t.cpu) {
        return Flow::ret(status.into());
    }
    Ok(Flow::Resume(Box::new(context)))
}
fn capture_context(c: &mut Ctx) -> ApiResult {
    let addr = c.ptr(0)?;
    let mut context = super::super::context::RegContext::capture(&c.t.cpu);
    context.set_pc(c.ret_addr);
    context.set_sp(
        c.entry_sp
            + if c.arch().is64() {
                if c.arch() == super::super::arch::WinArch::X64 {
                    8
                } else {
                    0
                }
            } else {
                8
            },
    );
    context.write(c.mem(), addr)?;
    Flow::void()
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::user::windows::arch::WinArch;
    use crate::user::windows::context::{INTEGER, RegContext};
    use crate::user::windows::hle::{ApiErr, Item, Value};
    use crate::user::windows::process::{WindowsConfig, WindowsProcess};

    #[test]
    fn nt_termination_self_paths_are_forced_all_abis() {
        for arch in WinArch::ALL {
            let image: &[u8] = match arch {
                WinArch::X86 => {
                    include_bytes!("../../../../tests/fixtures/user/windows/bin/x86/smoke.exe")
                }
                WinArch::X64 => {
                    include_bytes!("../../../../tests/fixtures/user/windows/bin/x64/smoke.exe")
                }
                WinArch::Arm64 => {
                    include_bytes!("../../../../tests/fixtures/user/windows/bin/arm64/smoke.exe")
                }
            };
            let mut config = WindowsConfig::new("terminate-test.exe", vec![]);
            config.seed = Some(1);
            config.arena_bytes = 64 << 20;
            let mut process = WindowsProcess::spawn_image(config, image.to_vec()).unwrap();
            let p = process.state_mut();
            let tid = *p.threads.keys().next().unwrap();
            let mut t = p.threads.remove(&tid).unwrap();
            let sp = t.cpu.sp();
            for (name, pseudo, process_exit) in [
                ("NtTerminateProcess", arch.ptr(u64::MAX), true),
                ("NtTerminateThread", arch.ptr(u64::MAX - 1), false),
            ] {
                let api = EXPORTS
                    .iter()
                    .find_map(|e| match &e.item {
                        Item::Func(api) if api.name == name => Some(api),
                        _ => None,
                    })
                    .unwrap();
                for handle in [pseudo, 0, 0x1234] {
                    match arch {
                        WinArch::X86 => {
                            p.space.w32(sp + 4, handle as u32).unwrap();
                            p.space.w32(sp + 8, 0xDEAD_BEEF).unwrap();
                        }
                        WinArch::X64 => {
                            t.cpu.set_gpr(1, handle);
                            t.cpu.set_gpr(2, 0xDEAD_BEEF);
                        }
                        WinArch::Arm64 => {
                            t.cpu.set_gpr(0, handle);
                            t.cpu.set_gpr(1, 0xDEAD_BEEF);
                        }
                    }
                    let mut c = Ctx {
                        p,
                        t: &mut t,
                        api,
                        entry_pc: 0,
                        entry_sp: sp,
                        ret_addr: 0,
                        cursor: sp,
                    };
                    c.set_last_error(0x7654_3210).unwrap();
                    let flow = (api.imp)(&mut c).unwrap();
                    if handle == 0x1234 {
                        assert!(
                            matches!(flow, Flow::Ret(Value::Int(status))
                            if status == u64::from(STATUS_INVALID_HANDLE)),
                            "{arch}: {name}"
                        );
                    } else if process_exit {
                        assert!(
                            matches!(flow, Flow::TerminateProcess(0xDEAD_BEEF)),
                            "{arch}: {name}"
                        );
                    } else {
                        assert!(
                            matches!(flow, Flow::TerminateThread(0xDEAD_BEEF)),
                            "{arch}: {name}"
                        );
                    }
                    assert_eq!(c.last_error().unwrap(), 0x7654_3210);
                }
            }
        }
    }

    #[test]
    fn ntcontinue_rejects_invalid_state_and_explicitly_rejects_alert_delivery() {
        let mut cfg = WindowsConfig::new("context-api-test.exe", Vec::new());
        cfg.seed = Some(1);
        cfg.arena_bytes = 64 << 20;
        let mut process = WindowsProcess::spawn_image(
            cfg,
            include_bytes!("../../../../tests/fixtures/user/windows/bin/x64/smoke.exe").to_vec(),
        )
        .unwrap();
        let p = process.state_mut();
        let tid = *p.threads.keys().next().unwrap();
        let mut t = p.threads.remove(&tid).unwrap();
        let api = EXPORTS
            .iter()
            .find_map(|export| match &export.item {
                Item::Func(api) if api.name == "NtContinue" => Some(api),
                _ => None,
            })
            .unwrap();
        let sp = t.cpu.sp();
        let address = sp - 0x800;
        let mut saved = RegContext::capture(&t.cpu);
        saved.set_gpr(0, 0x1234_5678);
        saved.set_flags(RegContext::arch_flag(p.arch) | 0x10);
        saved.write(&p.space, address).unwrap();
        t.cpu.set_gpr(1, address);
        t.cpu.set_gpr(2, 0);
        let old = RegContext::capture(&t.cpu);
        let mut c = Ctx {
            p,
            t: &mut t,
            api,
            entry_pc: 0,
            entry_sp: sp,
            ret_addr: 0,
            cursor: sp,
        };
        assert!(matches!(
            continue_context(&mut c).unwrap(),
            Flow::Ret(Value::Int(status)) if status == u64::from(STATUS_INVALID_PARAMETER)
        ));
        assert_eq!(RegContext::capture(&c.t.cpu).bytes(), old.bytes());
        saved.set_flags(RegContext::arch_flag(c.arch()) | INTEGER);
        saved.write(c.mem(), address).unwrap();
        assert!(matches!(continue_context(&mut c).unwrap(), Flow::Resume(_)));
        c.t.cpu.set_gpr(1, address + 1);
        assert!(matches!(
            continue_context(&mut c).unwrap(),
            Flow::Ret(Value::Int(status)) if status == u64::from(STATUS_INVALID_PARAMETER)
        ));
        c.t.cpu.set_gpr(1, address);
        c.t.cpu.set_gpr(2, 1);
        assert!(matches!(
            continue_context(&mut c),
            Err(ApiErr::Unimplemented(_))
        ));
        c.t.cpu.set_gpr(2, 0);
        c.t.cpu.set_gpr(1, u64::MAX - 15);
        assert!(matches!(continue_context(&mut c), Err(ApiErr::Fault(_))));
    }
}

//! Six-pointer WNF query conversion over immutable selected state.
use super::query::{guard_result, probe_write};
use crate::user::windows::hle::{ApiResult, Ctx, Flow};
use crate::user::windows::memory::Mem;
use crate::user::windows::nt::status::*;
use crate::user::windows::objects::Object;
use crate::user::windows::wnf::{Name, Record};

pub(super) fn query(c: &mut Ctx) -> ApiResult {
    let result = checked(c);
    guard_result(c, result)
}

fn checked(c: &mut Ctx) -> ApiResult {
    let (input, type_ptr, explicit, stamp_ptr, output, length_ptr) = (
        c.ptr(0)?,
        c.ptr(1)?,
        c.ptr(2)?,
        c.ptr(3)?,
        c.ptr(4)?,
        c.ptr(5)?,
    );
    let name = c.mem().u64(input)?;
    let Some(parsed) = Name::decode(name) else {
        return Flow::ret(STATUS_INVALID_PARAMETER.into());
    };
    let type_id = if type_ptr == 0 {
        None
    } else {
        Some(<[u8; 16]>::try_from(c.mem().bytes(type_ptr, 16)?).unwrap())
    };
    let capacity = c.mem().u32(length_ptr)?;
    probe_write(c, length_ptr, 4)?;
    probe_write(c, stamp_ptr, 4)?;
    if capacity != 0 {
        probe_write(c, output, capacity as usize)?;
    }
    let queries =
        c.p.objects
            .wnf_queries()
            .ok_or_else(|| c.unsupported("WNF query-state metadata was not selected"))?;
    if explicit != 0 {
        match parsed.scope {
            0 | 4 => return Flow::ret(STATUS_INVALID_PARAMETER.into()),
            1 => {
                if c.mem().u32(explicit)? != queries.session {
                    return Flow::ret(STATUS_INVALID_PARAMETER.into());
                }
            }
            2 => {
                let header = c.mem().bytes(explicit, 8)?;
                if header[0] != 1 || header[1] > 15 {
                    return Flow::ret(STATUS_INVALID_SID.into());
                }
                let sid = c.mem().bytes(explicit, 8 + 4 * usize::from(header[1]))?;
                let subject =
                    c.p.objects
                        .primary_token_subject()
                        .ok_or_else(|| c.unsupported("WNF user scope has no captured subject"))?;
                if sid != subject.user {
                    return Flow::ret(STATUS_OBJECT_NAME_NOT_FOUND.into());
                }
            }
            3 => {
                if explicit != c.arch().ptr(u64::MAX) {
                    if explicit == c.arch().ptr(u64::MAX - 1) {
                        return Flow::ret(STATUS_OBJECT_TYPE_MISMATCH.into());
                    }
                    match c.p.objects.get(explicit) {
                        None => return Flow::ret(STATUS_INVALID_HANDLE.into()),
                        Some(Object::Process { pid, .. }) if *pid == c.p.pid => {}
                        Some(Object::Process { .. }) => {
                            return Err(c.unsupported("WNF scope targets a different guest process"));
                        }
                        Some(_) => return Flow::ret(STATUS_OBJECT_TYPE_MISMATCH.into()),
                    }
                    // Native scope resolution accepts a process handle with
                    // granted access zero; it does not impose a query-right gate.
                }
            }
            _ => return Err(c.unsupported("unmeasured explicit WNF physical-machine scope")),
        }
    }
    let Some((definition, record)) = queries.get(name) else {
        if parsed.lifetime != 0 {
            return Err(c.unsupported("WNF nonprovisioned lifetime has no guest-owned state"));
        }
        return Flow::ret(STATUS_OBJECT_NAME_NOT_FOUND.into());
    };
    let data = match record {
        Record::Status(status) => return Flow::ret(u64::from(*status)),
        Record::Unavailable(reason) => return Err(c.unsupported(*reason)),
        Record::Data(data) => data,
    };
    if definition.type_id.is_some() && definition.type_id != type_id {
        return Flow::ret(STATUS_INVALID_PARAMETER.into());
    }
    let bytes = data.bytes.len() as u32;
    c.mem().w32(stamp_ptr, data.stamp)?;
    c.mem().w32(length_ptr, bytes)?;
    if capacity < bytes {
        return Flow::ret(STATUS_BUFFER_TOO_SMALL.into());
    }
    if bytes != 0 {
        c.mem().wr(output, &data.bytes)?;
    }
    Flow::ret(STATUS_SUCCESS.into())
}

//! Process notification ownership; delivery requires separate WNF state services.
use super::{ObjId, Object, Objects};
use crate::user::windows::wnf::{Catalog, Permission};
use std::collections::BTreeMap;

#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) struct Subscription {
    pub(crate) id: u64,
    pub(crate) change_stamp: u32,
    pub(crate) event_mask: u32,
    /// Queued metadata survives an absent notification Event and manual reset.
    /// Delivery/acknowledgement is a separate, currently unsupported service.
    pub(crate) pending_mask: u32,
}
#[derive(Debug, Default)]
pub(super) struct Subscriptions {
    catalog: Option<Catalog>,
    pub(super) records: BTreeMap<u64, Subscription>,
    next: u64,
}
fn levels(mask: u32) -> u32 {
    8 | if mask & 1 != 0 {
        2
    } else if mask & 0x0E != 0 {
        4
    } else {
        0
    }
}

impl Objects {
    pub(crate) fn wnf_queries(&self) -> Option<std::sync::Arc<crate::user::windows::wnf::Queries>> {
        self.wnf_subscriptions
            .catalog
            .as_ref()
            .and_then(Catalog::queries)
    }

    pub(crate) fn primary_token_subject(
        &self,
    ) -> Option<std::sync::Arc<crate::user::windows::security::Subject>> {
        self.wnf_subscriptions
            .catalog
            .as_ref()
            .and_then(Catalog::primary_subject)
    }
    /// Primary subject captured with the selected immutable native catalog.
    /// An absent capture is distinct from a non-AppContainer subject.
    pub(crate) fn primary_token_app_container(&self) -> Option<bool> {
        self.wnf_subscriptions
            .catalog
            .as_ref()
            .and_then(Catalog::primary_app_container)
    }

    pub(crate) fn select_wnf_catalog(&mut self, catalog: Catalog) {
        self.wnf_subscriptions.catalog = Some(catalog);
    }
    pub(crate) fn wnf_permission(&self, name: u64, mask: u32) -> Option<Permission> {
        self.wnf_subscriptions
            .catalog
            .as_ref()
            .map(|catalog| catalog.permission(name, mask))
    }
    pub(crate) fn wnf_subscription(&self, name: u64) -> Option<&Subscription> {
        self.wnf_subscriptions.records.get(&name)
    }
    /// O(log N) time/O(N) retained subscriptions, bounded by selected names.
    /// IDs are opaque private generations; no host subscription is created.
    pub(crate) fn subscribe_wnf(
        &mut self,
        name: u64,
        stamp: u32,
        mask: u32,
    ) -> Result<u64, &'static str> {
        if self.wnf_permission(name, mask) != Some(Permission::Allowed) || mask & !0x1F != 0 {
            return Err("WNF subscription was not admitted");
        }
        let previous = self.wnf_subscriptions.records.get(&name);
        let old_mask = previous.map_or(0, |sub| sub.event_mask);
        let old_levels = previous.map_or(0, |sub| levels(sub.event_mask));
        let arrived = mask & levels(mask) & (!old_mask | !old_levels);
        let pending = previous.map_or(0, |sub| sub.pending_mask & mask) | arrived;
        let id = if let Some(previous) = previous {
            previous.id
        } else {
            self.wnf_subscriptions
                .next
                .checked_add(1)
                .ok_or("WNF subscription generation exhausted")?
        };
        // A pinned registration must still designate an Event. Validate before
        // publishing a generation/record so a corrupted owner cannot half-commit.
        if let Some(event) = self.wnf_event
            && !matches!(self.obj(event), Some(Object::Event { .. }))
        {
            return Err("WNF notification Event ownership is inconsistent");
        }
        self.wnf_subscriptions.next = self.wnf_subscriptions.next.max(id);
        self.wnf_subscriptions.records.insert(
            name,
            Subscription {
                id,
                change_stamp: stamp,
                event_mask: mask,
                pending_mask: pending,
            },
        );
        if arrived != 0
            && let Some(event) = self.wnf_event
        {
            let Some(Object::Event { signaled, .. }) = self.obj_mut(event) else {
                unreachable!()
            };
            *signaled = 1;
        }
        Ok(id)
    }
    pub(crate) fn unsubscribe_wnf(&mut self, name: u64) -> bool {
        // Native unsubscribe discards its queued metadata but does not reset
        // the sticky notification Event; the completion service owns that step.
        self.wnf_subscriptions.records.remove(&name).is_some()
    }
    /// Atomically pins the first registration. The service checks type/grants
    /// before this busy check. Expected O(1) time and O(1) extra space.
    pub(crate) fn register_wnf_event(&mut self, id: ObjId) -> Result<bool, &'static str> {
        if self.wnf_event.is_some() {
            return Ok(false);
        }
        if !matches!(self.obj(id), Some(Object::Event { .. })) {
            return Err("WNF notification object is not an Event");
        }
        self.retain_many(&[id])?;
        self.wnf_event = Some(id);
        Ok(true)
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn native_wnf_subscription_generation_exhaustion_and_owner_failure_are_transactional() {
        let name = 0x41911A28A3BC10B5;
        let mut objects = Objects::default();
        objects.select_wnf_catalog(crate::user::windows::wnf::tests::catalog());
        let event = objects.create(Object::Event {
            manual: true,
            signaled: 0,
        });
        assert_eq!(objects.register_wnf_event(event), Ok(true));
        objects.wnf_subscriptions.next = u64::MAX;
        assert!(objects.subscribe_wnf(name, 0, 4).is_err());
        assert!(objects.wnf_subscription(name).is_none());
        assert!(matches!(
            objects.obj(event),
            Some(Object::Event { signaled: 0, .. })
        ));
        objects.wnf_subscriptions.next = 0;
        let id = objects.subscribe_wnf(name, 0, 4).unwrap();
        let before = objects.wnf_subscription(name).unwrap().clone();
        let owned = objects.objs.remove(&event).unwrap();
        assert!(objects.subscribe_wnf(name, 1, 8).is_err());
        assert_eq!(objects.wnf_subscription(name).unwrap(), &before);
        assert_eq!(objects.wnf_subscriptions.next, id);
        objects.objs.insert(event, owned);
        objects.wnf_subscriptions.next = u64::MAX;
        assert_eq!(objects.subscribe_wnf(name, 1, 8), Ok(id));
        assert_eq!(objects.wnf_subscription(name).unwrap().pending_mask, 8);
        objects.drain().for_each(drop);
        assert!(objects.wnf_subscription(name).is_none());
    }
    #[test]
    fn native_wnf_process_event_reference_overflow_is_transactional() {
        let mut objects = Objects::default();
        let id = objects.create(Object::Event {
            manual: true,
            signaled: 0,
        });
        objects.objs.get_mut(&id).unwrap().refs = u32::MAX;
        assert!(objects.register_wnf_event(id).is_err());
        assert_eq!(objects.wnf_event, None);
        assert_eq!(objects.objs[&id].refs, u32::MAX);
        objects.objs.get_mut(&id).unwrap().refs = 0;
        assert_eq!(objects.register_wnf_event(id), Ok(true));
        assert_eq!(objects.wnf_event, Some(id));
        assert_eq!(objects.objs[&id].refs, 1);
        assert_eq!(objects.register_wnf_event(id), Ok(false));
        assert_eq!(objects.objs[&id].refs, 1);
        objects.drain().for_each(drop);
        assert_eq!(objects.wnf_event, None);
    }
}

