//! Build29683 name validation and bounded classic-DACL admission.
use crate::user::windows::registry::Value;
pub(super) use crate::user::windows::security::{Group, Subject};
use std::collections::BTreeMap;
use std::io;
use std::sync::Arc;

const XOR_KEY: u64 = 0x41C6_4E6D_A3BC_0074;

#[derive(Debug, Clone, Copy)]
pub(crate) struct Name {
    pub(crate) lifetime: u8,
    pub(crate) scope: u8,
}
impl Name {
    pub(crate) fn decode(value: u64) -> Option<Self> {
        let bits = value ^ XOR_KEY;
        let scope = ((bits >> 6) & 15) as u8;
        let persistent = bits & 0x400 != 0;
        if bits & 15 != 1 || scope > 5 || (persistent && !matches!(scope, 0 | 2 | 4)) {
            return None;
        }
        Some(Self {
            lifetime: ((bits >> 4) & 3) as u8,
            scope,
        })
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum Permission {
    Missing,
    Denied,
    Unmodeled,
    Allowed,
}
#[derive(Debug, Clone, Default)]
pub(crate) struct Catalog {
    records: Arc<BTreeMap<u64, Option<u32>>>,
    primary_subject: Option<Arc<Subject>>,
    queries: Option<Arc<super::Queries>>,
}
fn invalid(message: &'static str) -> io::Error {
    io::Error::new(io::ErrorKind::InvalidData, message)
}
fn u16le(bytes: &[u8], at: usize) -> Option<u16> {
    Some(u16::from_le_bytes(bytes.get(at..at + 2)?.try_into().ok()?))
}
fn u32le(bytes: &[u8], at: usize) -> Option<u32> {
    Some(u32::from_le_bytes(bytes.get(at..at + 4)?.try_into().ok()?))
}
pub(super) fn sid(bytes: &[u8]) -> Option<&[u8]> {
    if bytes.first() != Some(&1) || *bytes.get(1)? > 15 {
        return None;
    }
    bytes.get(..8 + usize::from(bytes[1]) * 4)
}
fn matches(subject: &Subject, candidate: &[u8], deny: bool, restricted: bool) -> bool {
    if !restricted && subject.user == candidate {
        return true;
    }
    let groups = if restricted {
        &subject.restricted
    } else {
        &subject.groups
    };
    groups.iter().any(|group| {
        group.sid == candidate
            && if deny {
                group.attributes & (4 | 16) != 0
            } else {
                group.attributes & 4 != 0 && group.attributes & 16 == 0
            }
    })
}
fn grants(sd: &[u8], subject: &Subject) -> Option<u32> {
    // This profile admits an absent owner/group/SACL and classic, noninherited
    // allow/deny ACEs. Conditional/object ACEs, labels, AppContainers and other
    // descriptor controls remain explicit unmodeled inputs, never grant-all.
    if subject.app_container
        || !subject.restricted.is_empty()
        || sd.len() < 28
        || sd[0] != 1
        || sd[1] != 0
        || u16le(sd, 2)? != 0x8004
        || (4..16).any(|at| sd[at] != 0)
        || u32le(sd, 16)? != 20
    {
        return None;
    }
    let acl = &sd[20..];
    if !matches!(acl[0], 2 | 4)
        || acl[1] != 0
        || u16le(acl, 2)? as usize != acl.len()
        || u16le(acl, 6)? != 0
    {
        return None;
    }
    let mut entries = Vec::new();
    let mut at = 8;
    for _ in 0..u16le(acl, 4)? {
        let kind = *acl.get(at)?;
        let size = u16le(acl, at + 2)? as usize;
        if !matches!(kind, 0 | 1) || *acl.get(at + 1)? != 0 || size < 16 || size % 4 != 0 {
            return None;
        }
        let ace = acl.get(at..at.checked_add(size)?)?;
        let mask = u32le(ace, 4)?;
        let candidate = sid(&ace[8..])?;
        if candidate.len() + 8 != ace.len() {
            return None;
        }
        if mask & !3 != 0 && matches(subject, candidate, kind == 1, false) {
            return None;
        }
        entries.push((kind, mask, candidate));
        at += size;
    }
    if at != acl.len() {
        return None;
    }
    let allowed = |bit: u32, restricted: bool| {
        for &(kind, mask, candidate) in &entries {
            if mask & bit != 0 && matches(subject, candidate, kind == 1, restricted) {
                return kind == 0;
            }
        }
        false
    };
    Some(
        [1, 2]
            .into_iter()
            .filter(|&bit| {
                allowed(bit, false) && (subject.restricted.is_empty() || allowed(bit, true))
            })
            .fold(0, |mask, bit| mask | bit),
    )
}
impl Catalog {
    /// O(V log V + A*S) time and O(V) retained records; V<=4096 values,
    /// A total ACE count, S captured token SID count. No host pointer is retained.
    pub(crate) fn selected(values: Vec<Value>, subject: Subject) -> io::Result<Self> {
        if values.len() > 4096
            || subject.privileges.len() > 4096
            || sid(&subject.user) != Some(subject.user.as_slice())
            || subject
                .groups
                .iter()
                .chain(&subject.restricted)
                .any(|g| sid(&g.sid) != Some(g.sid.as_slice()))
        {
            return Err(invalid("WNF catalog/subject exceeds its bounded schema"));
        }
        let mut records = BTreeMap::new();
        for value in values {
            if value.kind != 3 || value.name.len() != 16 || value.data.len() < 4 {
                return Err(invalid(
                    "installed WNF value is not a named binary descriptor",
                ));
            }
            let name = value
                .name
                .iter()
                .try_fold(0u64, |n, &unit| {
                    char::from_u32(u32::from(unit))?
                        .to_digit(16)
                        .map(|digit| (n << 4) | u64::from(digit))
                })
                .ok_or_else(|| invalid("installed WNF name is not 16 hexadecimal units"))?;
            let parsed =
                Name::decode(name).ok_or_else(|| invalid("installed WNF name is malformed"))?;
            if parsed.lifetime != 0 || records.contains_key(&name) {
                return Err(invalid(
                    "installed WNF catalog is duplicate or not well-known",
                ));
            }
            let length = value.data.len();
            let maximum = u32le(&value.data, length - 4).unwrap();
            let grant = if parsed.scope == 3 && maximum <= 4096 {
                grants(&value.data[..length - 4], &subject)
            } else {
                None
            };
            records.insert(name, grant);
        }
        // A publish-only grant is not represented by the recorded provisioned
        // process catalog. Its mask conversion remains unmodeled rather than
        // applying an unverified access requirement.
        for grant in records.values_mut() {
            if *grant == Some(2) {
                *grant = None;
            }
        }
        Ok(Self {
            records: Arc::new(records),
            primary_subject: Some(Arc::new(subject)),
            queries: None,
        })
    }
    pub(crate) fn with_queries(mut self, queries: super::Queries) -> Self {
        self.queries = Some(Arc::new(queries));
        self
    }
    pub(crate) fn queries(&self) -> Option<Arc<super::Queries>> {
        self.queries.clone()
    }
    /// Retains the same validated primary-token property used for WNF grants.
    /// `None` is an absent snapshot, not a non-AppContainer token.
    pub(crate) fn primary_app_container(&self) -> Option<bool> {
        self.primary_subject
            .as_ref()
            .map(|subject| subject.app_container)
    }
    pub(crate) fn primary_subject(&self) -> Option<Arc<Subject>> {
        self.primary_subject.clone()
    }
    pub(crate) fn permission(&self, name: u64, event_mask: u32) -> Permission {
        let Some(grant) = self.records.get(&name) else {
            return Permission::Missing;
        };
        let Some(grant) = grant else {
            return Permission::Unmodeled;
        };
        let required = if event_mask == 0 {
            0
        } else if event_mask & 0x0E != 0 {
            3
        } else {
            1
        };
        if grant & required == required {
            Permission::Allowed
        } else {
            Permission::Denied
        }
    }
}

//! Read-only selection through fixed WNF metadata, before guest execution.
use super::query::{Definition, Queries, capture};
use std::ffi::{c_char, c_void};
use std::io;

#[link(name = "kernel32")]
unsafe extern "system" {
    fn GetModuleHandleW(name: *const u16) -> *mut c_void;
    fn GetProcAddress(module: *mut c_void, name: *const c_char) -> *mut c_void;
    fn GetCurrentProcessId() -> u32;
    fn ProcessIdToSessionId(process: u32, session: *mut u32) -> i32;
}
type Query = unsafe extern "system" fn(
    *const u64,
    *const u8,
    *const c_void,
    *mut u32,
    *mut u8,
    *mut u32,
) -> i32;

pub(super) fn snapshot(definitions: Vec<Definition>) -> io::Result<Queries> {
    let module_name: Vec<u16> = "ntdll.dll\0".encode_utf16().collect();
    // SAFETY: fixed terminated library/export names. Neither handle is owned
    // or retained; the process's installed NTDLL remains loaded during capture.
    let address = unsafe {
        let module = GetModuleHandleW(module_name.as_ptr());
        if module.is_null() {
            return Err(io::Error::last_os_error());
        }
        GetProcAddress(module, c"NtQueryWnfStateData".as_ptr())
    };
    if address.is_null() {
        return Err(io::Error::last_os_error());
    }
    // SAFETY: the fixed NTDLL export uses the six-argument NTAPI prototype.
    let query: Query = unsafe { std::mem::transmute(address) };
    let mut session = 0;
    // SAFETY: current process identity and exclusive DWORD output.
    if unsafe { ProcessIdToSessionId(GetCurrentProcessId(), &mut session) } == 0 {
        return Err(io::Error::last_os_error());
    }
    capture(definitions, session, |definition, bytes| {
        let mut stamp = 0;
        let mut length = bytes.len() as u32;
        let kind = definition
            .type_id
            .as_ref()
            .map_or(std::ptr::null(), |id| id.as_ptr());
        let output = if bytes.is_empty() {
            std::ptr::null_mut()
        } else {
            bytes.as_mut_ptr()
        };
        // SAFETY: all pointers refer to local owned metadata/output for this
        // fixed provisioned name. ExplicitScope is NULL. No guest inputs or
        // pointers enter acquisition, and native code cannot retain the slices.
        let status = unsafe {
            query(
                &definition.name,
                kind,
                std::ptr::null(),
                &mut stamp,
                output,
                &mut length,
            )
        };
        (status as u32, stamp, length as usize)
    })
}

//! Bounded immutable state selected from fixed WNF provisioning metadata.
use super::Name;
use crate::user::windows::nt::status::*;
use crate::user::windows::registry::Value;
use std::collections::BTreeMap;
use std::io;
use std::sync::Arc;

pub(super) const MAX_STATE_BYTES: usize = 65536;
const MAX_SELECTED_BYTES: usize = 16 << 20;

fn invalid(message: &'static str) -> io::Error {
    io::Error::new(io::ErrorKind::InvalidData, message)
}
fn u16le(bytes: &[u8], at: usize) -> Option<u16> {
    Some(u16::from_le_bytes(
        bytes.get(at..at.checked_add(2)?)?.try_into().ok()?,
    ))
}
fn u32le(bytes: &[u8], at: usize) -> Option<u32> {
    Some(u32::from_le_bytes(
        bytes.get(at..at.checked_add(4)?)?.try_into().ok()?,
    ))
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) struct Definition {
    pub(crate) name: u64,
    pub(crate) maximum: u32,
    pub(crate) type_id: Option<[u8; 16]>,
}
impl Definition {
    /// Fixed registry grammar: relative descriptor, maximum DWORD, optional GUID.
    /// O(B) validation, O(1) scratch; a record has at most 65536 metadata bytes.
    pub(super) fn parse(value: &Value) -> io::Result<Self> {
        if value.kind != 3 || value.name.len() != 16 || value.data.len() > MAX_STATE_BYTES {
            return Err(invalid("unmodeled WNF query provisioning record"));
        }
        let name = value
            .name
            .iter()
            .try_fold(0u64, |n, &u| {
                char::from_u32(u32::from(u))?
                    .to_digit(16)
                    .map(|d| (n << 4) | u64::from(d))
            })
            .ok_or_else(|| invalid("invalid WNF query provisioning name"))?;
        if Name::decode(name).is_none_or(|parsed| parsed.lifetime != 0) {
            return Err(invalid("WNF query provisioning name is not well-known"));
        }
        let raw = &value.data;
        if raw.len() < 24 || raw[0] != 1 || u16le(raw, 2).is_none_or(|c| c & 0x8000 == 0) {
            return Err(invalid("WNF query metadata has no relative descriptor"));
        }
        let mut end = 20usize;
        for index in 0..4 {
            let at = u32le(raw, 4 + 4 * index).unwrap() as usize;
            if at == 0 {
                continue;
            }
            if at < 20 || at % 4 != 0 {
                return Err(invalid("WNF query descriptor offset is invalid"));
            }
            let bytes = if index < 2 {
                let sid = raw
                    .get(at..)
                    .and_then(super::catalog::sid)
                    .ok_or_else(|| invalid("WNF query descriptor SID is invalid"))?;
                sid.len()
            } else {
                if !matches!(raw.get(at), Some(2 | 4)) {
                    return Err(invalid("WNF query descriptor ACL revision is unmodeled"));
                }
                let bytes = usize::from(
                    u16le(raw, at + 2)
                        .ok_or_else(|| invalid("WNF query descriptor ACL is truncated"))?,
                );
                if bytes < 8 {
                    return Err(invalid("WNF query descriptor ACL extent is invalid"));
                }
                bytes
            };
            let limit = at
                .checked_add(bytes)
                .filter(|&limit| limit <= raw.len())
                .ok_or_else(|| invalid("WNF query descriptor escapes its record"))?;
            end = end.max(limit);
        }
        let trailer = raw
            .get(end..)
            .ok_or_else(|| invalid("WNF query trailer is absent"))?;
        if !matches!(trailer.len(), 4 | 20) {
            return Err(invalid("WNF query provisioning trailer is unmodeled"));
        }
        Ok(Self {
            name,
            maximum: u32le(trailer, 0).unwrap(),
            type_id: (trailer.len() == 20).then(|| trailer[4..].try_into().unwrap()),
        })
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) struct Data {
    pub(crate) stamp: u32,
    pub(crate) bytes: Arc<[u8]>,
}
#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) enum Record {
    Data(Data),
    Status(u32),
    Unavailable(&'static str),
}
#[derive(Debug, Clone)]
pub(crate) struct Queries {
    records: BTreeMap<u64, (Definition, Record)>,
    pub(crate) session: u32,
}
impl Queries {
    pub(crate) fn selected(records: Vec<(Definition, Record)>, session: u32) -> io::Result<Self> {
        if records.len() > 4096 {
            return Err(invalid("WNF query record limit exceeded"));
        }
        let mut result = BTreeMap::new();
        let mut total = 0usize;
        for (definition, record) in records {
            if Name::decode(definition.name).is_none() || result.contains_key(&definition.name) {
                return Err(invalid("WNF query record is invalid or duplicate"));
            }
            match &record {
                Record::Data(data) => {
                    if data.bytes.len() > MAX_STATE_BYTES
                        || data.bytes.len() > definition.maximum as usize
                    {
                        return Err(invalid("WNF query data exceeds its declared limit"));
                    }
                    total = total
                        .checked_add(data.bytes.len())
                        .filter(|&n| n <= MAX_SELECTED_BYTES)
                        .ok_or_else(|| invalid("WNF query snapshot exceeds 16 MiB"))?;
                }
                Record::Status(status)
                    if !matches!(*status, STATUS_ACCESS_DENIED | STATUS_OBJECT_NAME_NOT_FOUND) =>
                {
                    return Err(invalid("WNF query recorded status is unmodeled"));
                }
                _ => {}
            }
            result.insert(definition.name, (definition, record));
        }
        Ok(Self {
            records: result,
            session,
        })
    }
    pub(crate) fn get(&self, name: u64) -> Option<&(Definition, Record)> {
        self.records.get(&name)
    }
}

/// Select at most six bounded native observations per definition. The caller
/// supplies a fixed metadata name, never a guest-selected name or pointer.
/// O(N log N + D) retained storage; D <= 16 MiB and N <= 4096.
pub(super) fn capture(
    definitions: Vec<Definition>,
    session: u32,
    mut query: impl FnMut(&Definition, &mut [u8]) -> (u32, u32, usize),
) -> io::Result<Queries> {
    let mut records = Vec::with_capacity(definitions.len().min(4096));
    if definitions.len() > 4096 {
        return Err(invalid("WNF query definition limit exceeded"));
    }
    let mut total = 0usize;
    for definition in definitions {
        let scope = Name::decode(definition.name)
            .ok_or_else(|| invalid("invalid WNF query definition"))?
            .scope;
        let mut record = Record::Unavailable("WNF state changed during bounded selection");
        if definition.maximum as usize > MAX_STATE_BYTES {
            record = Record::Unavailable("WNF state exceeds the 64 KiB selection limit");
        } else {
            let size = if scope == 3 {
                0
            } else {
                definition.maximum as usize
            };
            let observe = |query: &mut dyn FnMut(&Definition, &mut [u8]) -> (u32, u32, usize)| {
                let mut bytes = vec![0; size];
                let (status, stamp, length) = query(&definition, &mut bytes);
                if scope == 3 && matches!(status, STATUS_SUCCESS | STATUS_BUFFER_TOO_SMALL) {
                    // Only native read admission is selected. No host process-private
                    // data or change stamp becomes the new guest process's state.
                    return Record::Data(Data {
                        stamp: 0,
                        bytes: Arc::from([]),
                    });
                }
                if status == STATUS_SUCCESS && length <= bytes.len() {
                    bytes.truncate(length);
                    Record::Data(Data {
                        stamp,
                        bytes: bytes.into(),
                    })
                } else if matches!(status, STATUS_ACCESS_DENIED | STATUS_OBJECT_NAME_NOT_FOUND) {
                    Record::Status(status)
                } else {
                    Record::Unavailable("unmodeled native WNF state selection result")
                }
            };
            for _ in 0..3 {
                let first = observe(&mut query);
                let second = observe(&mut query);
                if first == second {
                    record = first;
                    break;
                }
            }
        }
        if let Record::Data(data) = &record {
            total = total
                .checked_add(data.bytes.len())
                .filter(|&n| n <= MAX_SELECTED_BYTES)
                .ok_or_else(|| invalid("WNF query capture exceeds 16 MiB"))?;
        }
        records.push((definition, record));
    }
    Queries::selected(records, session)
}

use super::query::*;
use super::tests::hex;
use crate::user::windows::registry::Value;
use serde_json::Value as Json;

fn values() -> Vec<Value> {
    let raw: Json = serde_json::from_str(include_str!("../../../../docs/specifications/windows/native-wnf-subscribe/native-wnf-subscribe-registry.json")).unwrap();
    raw.as_array()
        .unwrap()
        .iter()
        .map(|row| Value {
            name: row["name"].as_str().unwrap().encode_utf16().collect(),
            kind: 3,
            data: hex(row["data"].as_str().unwrap()),
        })
        .collect()
}
fn definition(name: u64, maximum: u32) -> Definition {
    Definition {
        name,
        maximum,
        type_id: None,
    }
}
const SYSTEM: u64 = 0x0280_032E_A3BC_0875;
const PROCESS: u64 = 0x4191_1A28_A3BC_10B5;

#[test]
fn query_provisioning_parses_every_native_record_and_the_single_typed_tail() {
    let all = values();
    assert_eq!(all.len(), 1613);
    let definitions = all
        .iter()
        .map(Definition::parse)
        .collect::<io::Result<Vec<_>>>()
        .unwrap();
    assert_eq!(
        definitions.iter().filter(|d| d.type_id.is_some()).count(),
        1
    );
    let typed = definitions.iter().find(|d| d.name == SYSTEM).unwrap();
    assert_eq!(typed.maximum, 8);
    assert_eq!(
        typed.type_id,
        Some(hex("6364f948d652854e9c02f2c14e17264e").try_into().unwrap())
    );
    let process = definitions.iter().find(|d| d.name == PROCESS).unwrap();
    assert_eq!(process.maximum, 0);
    assert_eq!(process.type_id, None);
}

#[test]
fn query_provisioning_refuses_malformed_offsets_sid_extents_and_unknown_trailers() {
    let value = values()
        .into_iter()
        .find(|v| String::from_utf16(&v.name).unwrap() == "0280032EA3BC0875")
        .unwrap();
    for length in 0..value.data.len() {
        let mut short = value.clone();
        short.data.truncate(length);
        // Removing exactly the optional GUID leaves the other admitted format.
        if length == value.data.len() - 16 {
            assert!(Definition::parse(&short).is_ok());
        } else {
            assert!(Definition::parse(&short).is_err(), "length {length}");
        }
    }
    for offset in [1u32, 16, u32::MAX, 0xFFFF_FFFC] {
        let mut broken = value.clone();
        broken.data[4..8].copy_from_slice(&offset.to_le_bytes());
        assert!(Definition::parse(&broken).is_err(), "offset {offset}");
    }
    let mut oversized = value.clone();
    oversized.data.resize(MAX_STATE_BYTES + 1, 0);
    assert!(Definition::parse(&oversized).is_err());
    let mut kind = value.clone();
    kind.kind = 1;
    assert!(Definition::parse(&kind).is_err());
    let mut name = value;
    name.name = "0000000000000000".encode_utf16().collect();
    assert!(Definition::parse(&name).is_err());
}

#[test]
fn query_capture_bounds_retries_and_never_imports_host_process_payload() {
    let mut calls = 0;
    let stable = capture(vec![definition(SYSTEM, 8)], 0, |_, bytes| {
        calls += 1;
        bytes.copy_from_slice(&[1, 0, 0, 0, 0, 0, 0, 0]);
        (STATUS_SUCCESS, 9, 8)
    })
    .unwrap();
    assert_eq!(calls, 2);
    assert_eq!(
        stable.get(SYSTEM).unwrap().1,
        Record::Data(Data {
            stamp: 9,
            bytes: Arc::from([1, 0, 0, 0, 0, 0, 0, 0])
        })
    );
    let mut calls = 0;
    let changing = capture(vec![definition(SYSTEM, 8)], 0, |_, _| {
        calls += 1;
        (STATUS_SUCCESS, calls, 0)
    })
    .unwrap();
    assert_eq!(calls, 6);
    assert!(matches!(
        changing.get(SYSTEM).unwrap().1,
        Record::Unavailable(_)
    ));
    let private = capture(vec![definition(PROCESS, 32)], 0, |_, bytes| {
        assert!(bytes.is_empty());
        (STATUS_BUFFER_TOO_SMALL, 99, 16)
    })
    .unwrap();
    assert_eq!(
        private.get(PROCESS).unwrap().1,
        Record::Data(Data {
            stamp: 0,
            bytes: Arc::from([])
        })
    );
    for status in [STATUS_ACCESS_DENIED, STATUS_OBJECT_NAME_NOT_FOUND] {
        let q = capture(vec![definition(SYSTEM, 8)], 0, |_, _| (status, 0, 8)).unwrap();
        assert_eq!(q.get(SYSTEM).unwrap().1, Record::Status(status));
    }
    let unavailable = capture(vec![definition(SYSTEM, u32::MAX)], 0, |_, _| {
        panic!("oversized capture must not call host")
    })
    .unwrap();
    assert!(matches!(
        unavailable.get(SYSTEM).unwrap().1,
        Record::Unavailable(_)
    ));
}

#[test]
fn query_catalog_rejects_duplicate_invalid_and_over_budget_data() {
    let row = (
        definition(SYSTEM, 8),
        Record::Data(Data {
            stamp: 1,
            bytes: Arc::from([0u8; 8]),
        }),
    );
    assert!(Queries::selected(vec![row.clone(), row], 0).is_err());
    assert!(
        Queries::selected(
            vec![(definition(0, 0), Record::Status(STATUS_ACCESS_DENIED))],
            0
        )
        .is_err()
    );
    assert!(
        Queries::selected(
            vec![(
                definition(SYSTEM, 0),
                Record::Data(Data {
                    stamp: 1,
                    bytes: Arc::from([1])
                })
            )],
            0
        )
        .is_err()
    );
    assert!(
        Queries::selected(
            vec![(
                definition(SYSTEM, 0),
                Record::Status(STATUS_INVALID_PARAMETER)
            )],
            0
        )
        .is_err()
    );
    let mut definitions = Vec::new();
    for i in 0..257 {
        definitions.push(definition(
            SYSTEM ^ ((i as u64) << 11),
            MAX_STATE_BYTES as u32,
        ));
    }
    let mut calls = 0;
    assert!(
        capture(definitions, 0, |_, bytes| {
            calls += 1;
            (STATUS_SUCCESS, 0, bytes.len())
        })
        .is_err()
    );
    assert_eq!(calls, 514);
}

#[cfg(windows)]
#[test]
fn native_query_snapshot_captures_typed_state_and_initializes_private_process_state() {
    let selected = super::snapshot().unwrap();
    let q = selected.queries().unwrap();
    let (definition, record) = q.get(SYSTEM).unwrap();
    assert_eq!(definition.maximum, 8);
    assert!(definition.type_id.is_some());
    assert_eq!(
        *record,
        Record::Data(Data {
            stamp: 1,
            bytes: Arc::from([1, 0, 0, 0, 0, 0, 0, 0])
        })
    );
    assert_eq!(
        q.get(PROCESS).unwrap().1,
        Record::Data(Data {
            stamp: 0,
            bytes: Arc::from([])
        })
    );
    assert!(selected.primary_subject().is_some());
}
